const INF = Infinity;
const graph = [[0, 4, 1], [INF, 0, INF], [INF, 2, 0]];
const dist = [0, INF, INF], used = [false, false, false];
for (let step = 0; step < 3; step++) {
  let u = -1;
  for (let v = 0; v < 3; v++) if (!used[v] && (u === -1 || dist[v] < dist[u])) u = v;
  if (u === -1 || dist[u] === INF) break;
  used[u] = true;
  for (let v = 0; v < 3; v++) dist[v] = Math.min(dist[v], dist[u] + graph[u][v]);
}
console.log(dist[1]);

const dist = [0, Infinity];
